1	import java.util.LinkedHashSet;
2	import java.util.Set;
3	
4	public class GameOfLife {
5	
6	    public Set<Cell> advance(Set<Cell> livingCells, int generations) {
7	        Set<Cell> current = livingCells;
8	        for (int generation = 0; generation < generations; generation++) {
9	            current = nextGeneration(current);
10	        }
11	        return current;
12	    }
13	
14	    public Set<Cell> nextGeneration(Set<Cell> livingCells) {
15	        Set<Cell> next = new LinkedHashSet<>();
16	        for (Cell cell : candidates(livingCells)) {
17	            if (isAliveNextGeneration(cell, livingCells)) {
18	                next.add(cell);
19	            }
20	        }
21	        return next;
22	    }
23	
24	    private boolean isAliveNextGeneration(Cell cell, Set<Cell> livingCells) {
25	        int livingNeighbours = countLivingNeighbours(cell, livingCells);
26	        return livingCells.contains(cell)
27	                ? survives(livingNeighbours)
28	                : isBorn(livingNeighbours);
29	    }
30	
31	    private Set<Cell> candidates(Set<Cell> livingCells) {
32	        Set<Cell> candidates = new LinkedHashSet<>(livingCells);
33	        for (Cell cell : livingCells) {
34	            candidates.addAll(cell.neighbours());
35	        }
36	        return candidates;
37	    }
38	
39	    private boolean survives(int livingNeighbours) {
40	        return livingNeighbours == 2 || livingNeighbours == 3;
41	    }
42	
43	    private boolean isBorn(int livingNeighbours) {
44	        return livingNeighbours == 3;
45	    }
46	
47	    private int countLivingNeighbours(Cell cell, Set<Cell> livingCells) {
48	        int count = 0;
49	        for (Cell neighbour : cell.neighbours()) {
50	            if (livingCells.contains(neighbour)) {
51	                count++;
52	            }
53	        }
54	        return count;
55	    }
56	}
