4	public record Cell(int x, int y) {
5	
6	    public List<Cell> neighbours() {
7	        List<Cell> neighbours = new ArrayList<>();
8	        for (int dx = -1; dx <= 1; dx++) {
9	            for (int dy = -1; dy <= 1; dy++) {
10	                if (dx != 0 || dy != 0) {
11	                    neighbours.add(new Cell(x + dx, y + dy));
12	                }
13	            }
14	        }
15	        return neighbours;
16	    }
