40	    void liveCellWithTwoNeighboursSurvives() {
41	        Set<Cell> next =
42	                nextGeneration(new Cell(0, 0), new Cell(1, 0), new Cell(2, 0), new Cell(1, 2));
43	
44	        assertTrue(next.contains(new Cell(1, 0)));
45	    }
46	
