49	        Set<Cell> next =
50	                nextGeneration(new Cell(0, 0), new Cell(1, 0), new Cell(0, 1), new Cell(1, 1));
51	
52	        assertTrue(next.contains(new Cell(0, 0)));
53	    }
54	
55	    @Test
56	    void liveCellWithMoreThanThreeNeighboursDiesOfOverpopulation() {
57	        Set<Cell> next = nextGeneration(
58	                new Cell(0, 0), new Cell(1, 0), new Cell(2, 0), new Cell(1, 1), new Cell(1, 2));
59	
60	        assertFalse(next.contains(new Cell(1, 1)));
61	    }
62	
